param(
  [string]$InstallDir = (Join-Path $env:LOCALAPPDATA "ShadowCarrier\chatgpt-runtime-policy-v0.1.1"),
  [switch]$Force,
  [switch]$Uninstall
)

$ErrorActionPreference = "Stop"
$Version = "0.1.1-experimental"

if ($Uninstall) {
  if (Test-Path $InstallDir) { Remove-Item -Recurse -Force $InstallDir }
  Write-Host "Removed Shadow Carrier ChatGPT Runtime Policy from $InstallDir"
  exit 0
}

if ((Test-Path $InstallDir) -and -not $Force) {
  throw "Install directory already exists: $InstallDir. Re-run with -Force to replace it."
}

New-Item -ItemType Directory -Force -Path $InstallDir | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $InstallDir "test") | Out-Null

$Payload = @{
  "activation-policy.mjs" = ""
  "test/activation-policy.test.mjs" = ""
  "README.md" = ""
  "manifest.json" = ""
}

foreach ($Entry in $Payload.GetEnumerator()) {
  $Target = Join-Path $InstallDir $Entry.Key
  $Parent = Split-Path -Parent $Target
  if ($Parent) { New-Item -ItemType Directory -Force -Path $Parent | Out-Null }
  [IO.File]::WriteAllBytes($Target, [Convert]::FromBase64String($Entry.Value))
}

$Manifest = Get-Content (Join-Path $InstallDir "manifest.json") -Raw | ConvertFrom-Json
foreach ($Prop in $Manifest.files.PSObject.Properties) {
  $Rel = $Prop.Name
  $Expected = $Prop.Value.sha256
  $Actual = (Get-FileHash -Algorithm SHA256 (Join-Path $InstallDir $Rel)).Hash.ToLowerInvariant()
  if ($Actual -ne $Expected) { throw "Checksum verification failed for $Rel" }
}

Write-Host "Installed Shadow Carrier ChatGPT Runtime Policy $Version"
Write-Host "Path: $InstallDir"
Write-Host "Status: INCOMPLETE / EXPERIMENTAL / DEFAULT OFF"
Write-Host "Important: this package does NOT automatically hook into ChatGPT built-in tools."

$Node = Get-Command node -ErrorAction SilentlyContinue
if ($Node) {
  $VersionText = (& node --version) -replace '^v',''
  $Major = [int](($VersionText -split '\.')[0])
  if ($Major -ge 20) {
    Push-Location $InstallDir
    try {
      & node --test "test/activation-policy.test.mjs"
      if ($LASTEXITCODE -ne 0) { throw "Self-test failed with exit code $LASTEXITCODE" }
      Write-Host "Self-test: PASS"
    } finally { Pop-Location }
  } else {
    Write-Warning "Node.js $VersionText detected. Node.js 20+ is recommended; self-test skipped."
  }
} else {
  Write-Warning "Node.js not found. Installation completed; self-test skipped."
}
